<?php require_once 'config.php';require_role('admin');$title='لوحة المدير';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['user_id']??0);$status=$_POST['status']??'active';if(in_array($status,['active','inactive','suspended'],true)&&$id!==user()['id']){$pdo->prepare('UPDATE users SET status=? WHERE id=?')->execute([$status,$id]);flash('تم تحديث حالة الحساب.');}go('admin.php');}$users=$pdo->query('SELECT id,full_name,email,role,status,created_at FROM users ORDER BY id DESC')->fetchAll();$apps=$pdo->query('SELECT ap.id,ap.start_time,ap.status,ap.consultation_price,c.full_name customer,p.title provider FROM appointments ap JOIN users c ON c.id=ap.customer_id JOIN provider_profiles p ON p.id=ap.provider_id ORDER BY ap.id DESC')->fetchAll();$counts=$pdo->query('SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM appointments) bookings,(SELECT COUNT(*) FROM provider_profiles) providers')->fetch();require 'includes/header.php';?><h1>لوحة مدير النظام</h1><div class="stats"><div class="stat"><strong><?=$counts['users']?></strong>مستخدم</div><div class="stat"><strong><?=$counts['providers']?></strong>مقدم خدمة</div><div class="stat"><strong><?=$counts['bookings']?></strong>حجز</div></div><h2>المستخدمون</h2><div class="tablewrap"><table><tr><th>الاسم</th><th>البريد</th><th>الدور</th><th>الحالة</th><th>تغيير الحالة</th></tr><?php foreach($users as $u):?><tr><td><?=h($u['full_name'])?></td><td><?=h($u['email'])?></td><td><?=h($u['role'])?></td><td><?=h($u['status'])?></td><td><?php if($u['id']!=user()['id']):?><form method="post"><input type="hidden" name="user_id" value="<?=$u['id']?>"><select name="status"><option value="active">نشط</option><option value="inactive">غير نشط</option><option value="suspended">موقوف</option></select><button class="btn">حفظ</button></form><?php else:?>حسابك الحالي<?php endif;?></td></tr><?php endforeach;?></table></div><h2>جميع الحجوزات</h2><div class="tablewrap"><table><tr><th>الزبون</th><th>مقدم الخدمة</th><th>التاريخ</th><th>السعر</th><th>الحالة</th></tr><?php foreach($apps as $a):?><tr><td><?=h($a['customer'])?></td><td><?=h($a['provider'])?></td><td><?=h($a['start_time'])?></td><td><?=number_format($a['consultation_price'],2)?> د.ل</td><td><?=h($a['status'])?></td></tr><?php endforeach;?></table></div><?php require 'includes/footer.php';?>
